use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{RwLock, broadcast, Notify};
use tokio::net::TcpListener;
use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt, BufReader};
use serde::{Deserialize, Serialize};

// Maximum bytes allowed per line read from a client to prevent unbounded
// memory allocation (DoS). Applies to both the username and each message.
const MAX_LINE_BYTES: u64 = 16 * 1024;

#[derive(Clone, Debug, Serialize, Deserialize)]
struct ChatMessage {
    sender: String,
    content: String,
    msg_type: String,
}

type PluginFn = Box<dyn Fn(&ChatMessage) -> Option<String> + Send + Sync>;

struct PluginRegistry {
    handlers: HashMap<String, PluginFn>,
    allowed_types: Vec<String>,
}

impl PluginRegistry {
    fn new() -> Self {
        let mut handlers: HashMap<String, PluginFn> = HashMap::new();
        handlers.insert("echo".to_string(), Box::new(|msg| {
            Some(format!("[echo] {}: {}", msg.sender, msg.content))
        }));
        handlers.insert("uppercase".to_string(), Box::new(|msg| {
            Some(format!("[upper] {}: {}", msg.sender, msg.content.to_uppercase()))
        }));
        handlers.insert("system".to_string(), Box::new(|msg| {
            Some(format!("[SYSTEM] {}", msg.content))
        }));
        let allowed_types = vec!["echo".to_string(), "uppercase".to_string()];
        Self { handlers, allowed_types }
    }

    fn resolve_handler(&self, handler_name: &str) -> Option<&PluginFn> {
        self.handlers.get(handler_name)
    }

    fn dispatch(&self, msg: &ChatMessage) -> Option<String> {
        // Resolve handler based on validated msg_type
        let handler_key = self.resolve_type_to_handler(&msg.msg_type);
        if let Some(handler) = self.resolve_handler(&handler_key) {
            handler(msg)
        } else {
            Some(format!("[chat] {}: {}", msg.sender, msg.content))
        }
    }

    fn resolve_type_to_handler(&self, msg_type: &str) -> String {
        // Only allow client to select from non-privileged handler types
        if self.allowed_types.contains(&msg_type.to_string()) {
            msg_type.to_string()
        } else {
            "echo".to_string()
        }
    }
}

struct ChatServer {
    connections: Arc<RwLock<HashMap<String, tokio::sync::mpsc::Sender<String>>>>,
    tx: broadcast::Sender<String>,
    shutdown: Arc<Notify>,
    plugins: Arc<PluginRegistry>,
}

impl ChatServer {
    fn new() -> Self {
        let (tx, _) = broadcast::channel(256);
        Self {
            connections: Arc::new(RwLock::new(HashMap::new())),
            tx,
            shutdown: Arc::new(Notify::new()),
            plugins: Arc::new(PluginRegistry::new()),
        }
    }

    async fn handle_client(
        connections: Arc<RwLock<HashMap<String, tokio::sync::mpsc::Sender<String>>>>,
        tx: broadcast::Sender<String>,
        shutdown: Arc<Notify>,
        plugins: Arc<PluginRegistry>,
        stream: tokio::net::TcpStream,
    ) {
        let (reader, mut writer) = stream.into_split();
        let mut buf_reader = BufReader::new(reader);
        let mut line = String::new();

        // Read username with a bounded read to avoid unbounded allocation.
        {
            let mut limited = (&mut buf_reader).take(MAX_LINE_BYTES);
            if limited.read_line(&mut line).await.unwrap_or(0) == 0 {
                return;
            }
        }
        let username = line.trim().to_string();
        line.clear();

        let (personal_tx, mut personal_rx) = tokio::sync::mpsc::channel::<String>(64);
        connections.write().await.insert(username.clone(), personal_tx);

        let mut rx = tx.subscribe();

        let write_task = tokio::spawn(async move {
            loop {
                tokio::select! {
                    msg = rx.recv() => {
                        if let Ok(msg) = msg {
                            let _ = writer.write_all(msg.as_bytes()).await;
                            let _ = writer.write_all(b"\n").await;
                        }
                    }
                    msg = personal_rx.recv() => {
                        if let Some(msg) = msg {
                            let _ = writer.write_all(msg.as_bytes()).await;
                            let _ = writer.write_all(b"\n").await;
                        }
                    }
                }
            }
        });

        loop {
            line.clear();
            tokio::select! {
                result = async {
                    let mut limited = (&mut buf_reader).take(MAX_LINE_BYTES);
                    limited.read_line(&mut line).await
                } => {
                    match result {
                        Ok(0) | Err(_) => break,
                        Ok(_) => {
                            let trimmed = line.trim();
                            if let Ok(msg) = serde_json::from_str::<ChatMessage>(trimmed) {
                                // Plugin dispatch validates msg_type against allowlist
                                if let Some(output) = plugins.dispatch(&msg) {
                                    let _ = tx.send(output);
                                }
                            }
                        }
                    }
                }
                _ = shutdown.notified() => {
                    let shutdown_msg = ChatMessage {
                        sender: "server".to_string(),
                        content: "Server shutting down".to_string(),
                        msg_type: "system".to_string(),
                    };
                    // Internal dispatch bypasses allowlist check since msg is server-generated
                    if let Some(handler) = plugins.resolve_handler("system") {
                        if let Some(output) = handler(&shutdown_msg) {
                            let _ = tx.send(output);
                        }
                    }
                    break;
                }
            }
        }

        write_task.abort();
        connections.write().await.remove(&username);
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let server = ChatServer::new();
    let listener = TcpListener::bind("127.0.0.1:8080").await?;
    let shutdown = server.shutdown.clone();

    tokio::spawn(async move {
        tokio::signal::ctrl_c().await.ok();
        shutdown.notify_waiters();
    });

    loop {
        tokio::select! {
            accept = listener.accept() => {
                if let Ok((stream, _)) = accept {
                    let conns = server.connections.clone();
                    let tx = server.tx.clone();
                    let shut = server.shutdown.clone();
                    let plugins = server.plugins.clone();
                    tokio::spawn(ChatServer::handle_client(conns, tx, shut, plugins, stream));
                }
            }
            _ = server.shutdown.notified() => {
                println!("Shutting down gracefully...");
                break;
            }
        }
    }
    Ok(())
}
